window.PORTFOLIO_PROJECTS={"homeslice": {"title": "HomeSlice Kitchen", "intro": "A selection of promotional work from my HomeSlice Kitchen portfolio collection, including social graphics, restaurant banners, and offers.", "image": "assets/social.webp", "alt": "HomeSlice Wednesday pizza promotion design", "direction": "Bold red and warm cream, playful illustration, and a clear offer hierarchy create an approachable visual language for a food and hospitality brand.", "applications": "Promotional graphics, banners, discount materials, and social media posts.", "url": "https://drive.google.com/drive/folders/16RRYc4xHmNSyLL5xsDmEeMTQOiWJZFMu", "gallery": ["assets/homeslice.webp", "assets/social.webp", "assets/flyer.webp"]}, "medical": {"title": "Sante Surgery Center", "intro": "A healthcare logo design from my portfolio, pairing a strong wordmark with a restrained blue and green palette.", "image": "assets/medical.webp", "alt": "Sante Surgery Center blue and green wordmark", "direction": "A geometric wordmark and a crisp green accent create a clear, professional identity. The supporting descriptor gives the mark a readable hierarchy.", "applications": "Primary wordmark, logo composition, and healthcare identity exploration.", "url": "https://drive.google.com/file/d/1rS_Xj9k6Cu8Xkhvpmz7Rgh5eybtViXIw/view?usp=drivesdk", "gallery": []}, "packaging": {"title": "Chocolate, reimagined.", "intro": "A packaging study from my portfolio, presented as a product mockup. This is a design exploration, without claiming a commissioned relationship with the depicted brand.", "image": "assets/chocolate-packaging.webp", "alt": "Chocolate wrapper design study presented in a realistic product mockup", "direction": "Warm yellow, bold brand recognition, and a product-focused composition explore how color and hierarchy can make a familiar format feel fresh.", "applications": "Wrapper design, packaging layout, and product mockup. The project collection also includes structural packaging studies.", "url": "https://drive.google.com/drive/folders/1qbegKQxDV-GOIV87nTGYjw_N-WTULCpQ", "gallery": ["assets/coffee.webp"]}, "vehicle": {"title": "HomeSlice, on the move.", "intro": "A vehicle graphics presentation from my portfolio, showing the HomeSlice Kitchen identity across a Nissan S-Cargo. The mockup presents front, side and rear views; it is a design visualization rather than a photograph of an installed wrap.", "image": "assets/vehicle-side.webp", "alt": "HomeSlice yellow Nissan S-Cargo vehicle graphics side view", "direction": "A warm yellow base, red brand accents, and food illustrations carry the identity across the body panels. The three views show how the layout adapts around windows, doors, and changing vehicle proportions.", "applications": "Vehicle graphics concept, brand placement, and multi-angle mockup presentation. Original third-party mockup watermarks are preserved.", "url": "https://drive.google.com/drive/folders/1CLAbbioDlb2HiPBUyFTtSu3-fDwlLaD5", "gallery": ["assets/vehicle-front.webp", "assets/vehicle-back.webp", "assets/vehicle-bus.webp"]}, "app": {"title": "Author’s Odyssey", "intro": "An ebook app interface study from my UX/UI portfolio. The screen collection explores onboarding, account access, book discovery, a reading view, and personalization. Presented as a visual design study, not a live or usability-tested application.", "image": "assets/app-1.webp", "alt": "Author’s Odyssey ebook mobile app interface board showing onboarding, login, book discovery and reading screens", "direction": "A restrained interface gives book covers room to stand out. Consistent mobile frames, readable text hierarchy, and recurring navigation connect the visual flow from entry screens to the reading experience.", "applications": "Mobile app screen design, onboarding, account screens, book discovery, reader interface, and personalization concepts.", "url": "https://drive.google.com/drive/folders/12cyEEeNF0Zaek2QjGxZXxr_MClmrE15T", "gallery": []}, "coffee": {"title": "The Coffee Break", "intro": "A Coffee Bean packaging study from my portfolio, combining a matcha coffee carton presentation with structural layout artwork. Shown as an independent design study without claiming a commissioned relationship with the depicted brand.", "image": "assets/pack-1.webp", "alt": "The Coffee Break matcha coffee carton packaging study with front and back panels and product mockups", "direction": "Fresh green tones, matcha imagery, and clear front-panel hierarchy build a coherent product presentation. The additional structural layout shows the panel arrangement behind the finished mockup.", "applications": "Carton packaging study, panel layout, product graphics, and three-dimensional packaging presentation.", "url": "https://drive.google.com/drive/folders/1qbegKQxDV-GOIV87nTGYjw_N-WTULCpQ", "gallery": ["assets/coffee.webp", "assets/pack-2.webp"]}, "century": {"title": "Century Tuna", "intro": "A canned-product packaging study from my portfolio, presented through multiple product mockups. This is an independent design exploration, without claiming a commissioned relationship with the depicted brand.", "image": "assets/pack-3.webp", "alt": "Century Tuna flakes chili and lime can label design study", "direction": "The wraparound label brings together brand recognition, product imagery, and a green flavor palette. The alternate mockup shows the relationship between the front label and supporting side information.", "applications": "Can-label design, wraparound packaging layout, and product mockup presentation.", "url": "https://drive.google.com/drive/folders/1qbegKQxDV-GOIV87nTGYjw_N-WTULCpQ", "gallery": ["assets/pack-4.webp"]}, "apparel": {"title": "CS Wizards", "intro": "A supplied apparel design presentation exploring graphic placement across a coordinated front and back shirt layout.", "image": "assets/apparel.webp", "alt": "CS Wizards portfolio artwork", "direction": "Composition, visual hierarchy, and carefully considered detail bring the idea into focus.", "applications": "Apparel design exploration. Explore the original collection for related work.", "url": "https://drive.google.com/drive/folders/1tRuo3gSvFvvvR3Tyom_qMJnjFQtQ4jax", "gallery": []}, "thumbnails": {"title": "Shall I run away to sea?", "intro": "An alternate YouTube thumbnail from my collection, pairing a sailing ship with a portrait and an expressive headline.", "image": "assets/sailing-thumbnail.webp", "alt": "Sailing YouTube thumbnail with a portrait, tall ship and the headline Shall I run away to sea?", "direction": "A prominent portrait, atmospheric blue tones, and contrasting type establish a clear focal point at thumbnail size.", "applications": "YouTube thumbnail design and alternate headline composition.", "url": "https://drive.google.com/drive/folders/1c7HO-33fnHzJzTnV3qnC15y75ku38mnd", "gallery": ["assets/sailing-thumbnail-alt.webp"]}, "illustration": {"title": "From sketch to character.", "intro": "A character illustration study exploring the progression from sketch to clean linework.", "image": "assets/illustration.webp", "alt": "From sketch to character. portfolio artwork", "direction": "Composition, visual hierarchy, and carefully considered detail bring the idea into focus.", "applications": "Illustration design exploration. Explore the original collection for related work.", "url": "https://drive.google.com/drive/folders/1KjXk3uvbVCgjwjP6H4f_MHzJaLyJJw6u", "gallery": []}, "digitalart": {"title": "A story in every line.", "intro": "A digital inking study from my portfolio, exploring character, environment, and the detail of linework.", "image": "assets/digitalart.webp", "alt": "A story in every line. portfolio artwork", "direction": "Composition, visual hierarchy, and carefully considered detail bring the idea into focus.", "applications": "Illustration design exploration. Explore the original collection for related work.", "url": "https://drive.google.com/drive/folders/10LmCZjwW2DYGkXD1lrVEL8gPr5mUSz8U", "gallery": []}, "poster": {"title": "TBI Workshop Series", "intro": "A workshop speaker poster for traumatic brain injury care, shown alongside photographs of the printed design at the event.", "image": "assets/workshop-in-use.webp", "alt": "TBI Workshop Series poster displayed beside speakers during the event", "direction": "A structured speaker layout, blue and green accents, and organized credential panels make a dense information set easier to scan.", "applications": "Workshop speaker poster and event display. The gallery includes event photographs and welcome signage.", "url": "", "gallery": ["assets/workshop-poster.webp", "assets/workshop-welcome.webp"]}, "ecommerce": {"title": "Knight Bites", "intro": "A landscape product advertising sample from my portfolio, combining sleep-gummy packaging, lifestyle photography, and a bold headline.", "image": "assets/knight-bites-ad.webp", "alt": "Knight Bites sleep gummies advertising design in blue with product packaging, lifestyle photography and white headline", "direction": "A coordinated blue palette connects the packaging and lifestyle imagery. Curved graphic shapes and bold white type guide attention through the composition.", "applications": "Landscape product advertising and digital campaign artwork.", "url": "https://drive.google.com/drive/folders/14ae1k8f3ljadEvvb8LD6VAxjDZoHSmaa", "gallery": []}, "dentrix": {"title": "Simply Dentrix", "intro": "A dental website project I worked on, shown here with the homepage header and hero. Visit the website to explore the published presentation.", "image": "assets/simply-dentrix-homepage.webp", "alt": "Simply Dentrix homepage with blue tooth logo, navigation and premium dental restorations hero", "direction": "A white header gives the blue dental identity room to stand out. The navy hero pairs a bold headline with clinical imagery, clear calls to action, and supporting service information.", "applications": "Website design and content presentation.", "url": "https://www.simplydentrix.com/", "gallery": []}, "flags": {"title": "HomeSlice, out in the world.", "intro": "Printed HomeSlice promotional materials, photographed in use: a handheld flag, a feather flag, and takeaway flyers.", "image": "assets/homeslice-feather-flag.webp", "alt": "Printed HomeSlice feather flag displayed outdoors", "direction": "Red lettering and a checkerboard motif carry the restaurant identity across different print sizes and formats.", "applications": "Feather flag, handheld flag, and printed promotional flyers.", "url": "https://drive.google.com/drive/folders/16RRYc4xHmNSyLL5xsDmEeMTQOiWJZFMu", "gallery": ["assets/homeslice-handheld-flag.webp", "assets/homeslice-printed-flyers.webp"]}};
